use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl < S > ChromeLayerBuilder < S > where S : Subscriber + for < 'span > LookupSpan < 'span > + Send + Sync , { pub fn new () -> Self { ChromeLayerBuilder { out_writer : None , name_fn : None , cat_fn : None , include_args : false , include_locations : true , trace_style : TraceStyle :: Threaded , _inner : PhantomData , } } # [doc = " Set the file to which to output the trace."] # [doc = ""] # [doc = " Defaults to `./trace-{unix epoch in micros}.json`."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " If `file` could not be opened/created. To handle errors,"] # [doc = " open a file and pass it to [`writer`](crate::ChromeLayerBuilder::writer) instead."] pub fn file < P : AsRef < Path > > (self , file : P) -> Self { self . writer (std :: fs :: File :: create (file) . expect ("Failed to create trace file.")) } # [doc = " Supply an arbitrary writer to which to write trace contents."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " # use tracing_chrome::ChromeLayerBuilder;"] # [doc = " # use tracing_subscriber::prelude::*;"] # [doc = " let (layer, guard) = ChromeLayerBuilder::new().writer(std::io::sink()).build();"] # [doc = " # tracing_subscriber::registry().with(layer).init();"] # [doc = " ```"] pub fn writer < W : Write + Send + 'static > (mut self , writer : W) -> Self { self . out_writer = Some (Box :: new (writer)) ; self } # [doc = " Include arguments in each trace entry."] # [doc = ""] # [doc = " Defaults to `false`."] # [doc = ""] # [doc = " Includes the arguments used when creating a span/event"] # [doc = " in the \"args\" section of the trace entry."] pub fn include_args (mut self , include : bool) -> Self { self . include_args = include ; self } # [doc = " Include file+line with each trace entry."] # [doc = ""] # [doc = " Defaults to `true`."] # [doc = ""] # [doc = " This can add quite a bit of data to the output so turning"] # [doc = " it off might be helpful when collecting larger traces."] pub fn include_locations (mut self , include : bool) -> Self { self . include_locations = include ; self } # [doc = " Sets the style used when recording trace events."] # [doc = ""] # [doc = " See [`TraceStyle`](crate::TraceStyle) for details."] pub fn trace_style (mut self , style : TraceStyle) -> Self { self . trace_style = style ; self } # [doc = " Allows supplying a function that derives a name from"] # [doc = " an Event or Span. The result is used as the \"name\" field"] # [doc = " on trace entries."] # [doc = ""] # [doc = " # Example"] # [doc = " ```"] # [doc = " use tracing_chrome::{ChromeLayerBuilder, EventOrSpan};"] # [doc = " use tracing_subscriber::{registry::Registry, prelude::*};"] # [doc = ""] # [doc = " let (chrome_layer, _guard) = ChromeLayerBuilder::new().name_fn(Box::new(|event_or_span| {"] # [doc = "     match event_or_span {"] # [doc = "         EventOrSpan::Event(ev) => { ev.metadata().name().into() },"] # [doc = "         EventOrSpan::Span(_s) => { \"span\".into() },"] # [doc = "     }"] # [doc = " })).build();"] # [doc = " tracing_subscriber::registry().with(chrome_layer).init()"] # [doc = " ```"] pub fn name_fn (mut self , name_fn : NameFn < S >) -> Self { self . name_fn = Some (name_fn) ; self } # [doc = " Allows supplying a function that derives a category from"] # [doc = " an Event or Span. The result is used as the \"cat\" field on"] # [doc = " trace entries."] # [doc = ""] # [doc = " # Example"] # [doc = " ```"] # [doc = " use tracing_chrome::{ChromeLayerBuilder, EventOrSpan};"] # [doc = " use tracing_subscriber::{registry::Registry, prelude::*};"] # [doc = ""] # [doc = " let (chrome_layer, _guard) = ChromeLayerBuilder::new().category_fn(Box::new(|_| {"] # [doc = "     \"my_module\".into()"] # [doc = " })).build();"] # [doc = " tracing_subscriber::registry().with(chrome_layer).init()"] # [doc = " ```"] pub fn category_fn (mut self , cat_fn : NameFn < S >) -> Self { self . cat_fn = Some (cat_fn) ; self } # [doc = " Creates a [`ChromeLayer`](crate::ChromeLayer) and associated [`FlushGuard`](crate::FlushGuard)."] # [doc = ""] # [doc = " # Panics"] # [doc = ""] # [doc = " If no file or writer was specified and the default trace file could not be opened/created."] pub fn build (self) -> (ChromeLayer < S > , FlushGuard) { ChromeLayer :: new (self) } }